import{_ as e,o as d,c as o,ag as r}from"./chunks/framework.DNmTgtHf.js";const m=JSON.parse('{"title":"Part 23 — GenAI & LLMs","description":"","frontmatter":{},"headers":[],"relativePath":"todo/study_plan/parts/Part_23_GenAI.md","filePath":"todo/study_plan/parts/Part_23_GenAI.md"}'),n={name:"todo/study_plan/parts/Part_23_GenAI.md"};function i(s,t,a,l,c,h){return d(),o("div",null,[...t[0]||(t[0]=[r('<h1 id="part-23-—-genai-llms" tabindex="-1">Part 23 — GenAI &amp; LLMs <a class="header-anchor" href="#part-23-—-genai-llms" aria-label="Permalink to &quot;Part 23 — GenAI &amp; LLMs&quot;">​</a></h1><blockquote><p><strong>Phase placement: Consolidation only.</strong> This Part has zero 🔴 rows — nothing here is required for SDE2/SDE3 KYC-backend interviews in the Sprint window. The 🟠 items are senior-fluency-nice-to-have but ~40 hrs is a heavy Sprint cost for a topic adjacent to your stack. Treat this Part as Month 4+ material. If you have an AI/ML-heavy interview in the Sprint window, promote rows 1, 5, 6, 25 (attention basics, prompt engineering, function calling, prompt injection) — that&#39;s ~7 hrs and covers the senior-fluency baseline.</p></blockquote><blockquote><p><strong>Sprint allocation:</strong> Deferred to Consolidation (Month 4+) — zero 🔴 rows; no Sprint coverage required. <strong>Budget: 0 hrs in Sprint (deferred).</strong></p></blockquote><h2 id="_23-genai-llms-—-topic-inventory" tabindex="-1">23 GenAI &amp; LLMs — topic inventory <a class="header-anchor" href="#_23-genai-llms-—-topic-inventory" aria-label="Permalink to &quot;23 GenAI &amp; LLMs — topic inventory&quot;">​</a></h2><table tabindex="0"><thead><tr><th>#</th><th>Topic</th><th>Tags</th><th>Tier</th><th>Time</th><th>Done</th><th>Partial</th><th>Grilling</th><th>Visit Again</th><th>Notes</th><th>Resources</th></tr></thead><tbody><tr><td>1</td><td>Transformer architecture intuition — attention, embeddings, tokens</td><td>🟠 💼 🆕</td><td>MP</td><td>1.5 hrs</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td></td><td>📺 Andrej Karpathy — &quot;Let&#39;s build GPT&quot; (free YouTube, ~2 hr; for intuition)</td></tr><tr><td>2</td><td>Context window, attention cost (O(n²))</td><td>🟠 💼 🆕</td><td>M</td><td>45 min</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td></td><td></td></tr><tr><td>3</td><td>Pre-training vs instruction tuning vs RLHF (high level)</td><td>🟠 💼 🆕</td><td>M</td><td>1 hr</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td></td><td></td></tr><tr><td>4</td><td>Open vs closed models — Llama, Mistral, Claude, GPT, Gemini</td><td>🟠 💼 🆕</td><td>M</td><td>45 min</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td></td><td></td></tr><tr><td>5</td><td>Prompt engineering — system prompts, few-shot, CoT, structured output</td><td>🟠 💼 🆕</td><td>MP</td><td>2 hrs</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td></td><td>💻 Warm-up: write 3 prompts for the same task (zero-shot, few-shot with 2 examples, CoT) — compare outputs (30 min)</td></tr><tr><td>6</td><td>Function calling / tool use</td><td>🟠 💼 🆕</td><td>MP</td><td>2 hrs</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td></td><td>💻 Warm-up: Claude / OpenAI function calling — define a tool schema, call API, parse tool response, return result (30 min)</td></tr><tr><td>7</td><td>Streaming responses, token-by-token UX</td><td>🟠 💼 🆕</td><td>MP</td><td>1.5 hrs</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td></td><td></td></tr><tr><td>8</td><td>Output validation, JSON mode, schema-enforced output</td><td>🟠 💼 🆕</td><td>MP</td><td>1.5 hrs</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td></td><td></td></tr><tr><td>9</td><td>Cost &amp; latency — tokens in / out, model selection ladder</td><td>🟠 💼 🆕</td><td>MP</td><td>1.5 hrs</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td></td><td></td></tr><tr><td>10</td><td>Caching strategies for LLM calls (prompt caching, semantic caching)</td><td>🟠 💼 🆕</td><td>MP</td><td>1.5 hrs</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td></td><td></td></tr><tr><td>11</td><td>LLM observability — LangSmith, Helicone, Langfuse, Phoenix</td><td>🟠 💼 🆕</td><td>M</td><td>1 hr</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td></td><td></td></tr><tr><td>12</td><td>Embeddings — what they are, similarity metrics</td><td>🟠 💼 🆕</td><td>MP</td><td>1.5 hrs</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td></td><td></td></tr><tr><td>13</td><td>Vector databases — pgvector, Pinecone, Weaviate, Milvus, OpenSearch k-NN</td><td>🟠 💼 🆕</td><td>MP</td><td>1.5 hrs</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td></td><td></td></tr><tr><td>14</td><td>Chunking strategies, overlap, hierarchical</td><td>🟠 💼 🆕</td><td>MP</td><td>1.5 hrs</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td></td><td></td></tr><tr><td>15</td><td>Hybrid search — BM25 + vector</td><td>🟠 💼 🆕</td><td>MP</td><td>1.5 hrs</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td></td><td></td></tr><tr><td>16</td><td>Reranking — Cohere / cross-encoder</td><td>🟠 💼 🆕</td><td>MP</td><td>1.5 hrs</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td></td><td></td></tr><tr><td>17</td><td>Failure modes — bad chunks, retrieval misses, hallucinations under context</td><td>🟠 💼 🆕</td><td>MP</td><td>1.5 hrs</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td></td><td></td></tr><tr><td>18</td><td>Agent loop — plan, act, observe, reflect</td><td>🟠 💼 🆕</td><td>MP</td><td>1.5 hrs</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td></td><td></td></tr><tr><td>19</td><td>ReAct pattern, function calling for tools</td><td>🟠 💼 🆕</td><td>MP</td><td>1.5 hrs</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td></td><td></td></tr><tr><td>20</td><td>Multi-step agents — when to use, when not</td><td>🟠 💼 🆕</td><td>M</td><td>1 hr</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td></td><td></td></tr><tr><td>21</td><td>MCP (Model Context Protocol) — what it is, how servers / clients work, why it standardizes tool access</td><td>🟠 💼 🆕</td><td>MP</td><td>2 hrs</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td></td><td></td></tr><tr><td>22</td><td>Building MCP servers (your future leverage)</td><td>🟠 💼 🆕</td><td>D</td><td>2 hrs 30 min</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td></td><td>💻 Warm-up: write a minimal MCP server in Python or TypeScript exposing one tool, connect to Claude Desktop, invoke (30 min)</td></tr><tr><td>23</td><td>Evals — golden sets, LLM-as-judge, metric design</td><td>🟠 💼 🆕</td><td>MP</td><td>2 hrs</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td></td><td></td></tr><tr><td>24</td><td>Hallucination detection</td><td>🟠 💼 🆕</td><td>MP</td><td>1.5 hrs</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td></td><td></td></tr><tr><td>25</td><td>Prompt injection — direct, indirect, defense</td><td>🟠 💼 🔐 🆕</td><td>D</td><td>2.5 hrs</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td></td><td></td></tr><tr><td>26</td><td>Data leakage from prompts</td><td>🟠 💼 🔐 🆕</td><td>MP</td><td>1.5 hrs</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td></td><td></td></tr><tr><td>27</td><td>Multi-modal — vision, audio</td><td>🟡 🆕</td><td>M</td><td>1 hr</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td></td><td></td></tr><tr><td>28</td><td>PII redaction in prompts / responses</td><td>🟡 🆕</td><td>MP</td><td>1.5 hrs</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td></td><td></td></tr></tbody></table><h2 id="time-summary" tabindex="-1">Time summary <a class="header-anchor" href="#time-summary" aria-label="Permalink to &quot;Time summary&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Scope</th><th>Hours (zero baseline)</th><th>Weeks @ 10–12 hrs/wk</th><th>Actual time</th></tr></thead><tbody><tr><td>🔴 MUST only (Sprint priority — 3-month plan)</td><td>~0 hrs (no 🔴 — 🟠 is the baseline here)</td><td>~0 wk</td><td></td></tr><tr><td>🔴 + 🟠 HIGH (must + high — senior coverage)</td><td>~40.5 hrs</td><td>~3.7 wk</td><td></td></tr><tr><td>Full Part (all items including 🟡)</td><td>~43 hrs</td><td>~3.9 wk</td><td></td></tr></tbody></table><h2 id="frequently-asked" tabindex="-1">Frequently asked <a class="header-anchor" href="#frequently-asked" aria-label="Permalink to &quot;Frequently asked&quot;">​</a></h2><ol><li><strong>Q:</strong> Explain attention in 2 minutes. Why does it scale O(n²)? <ul><li><strong>Why asked:</strong> Modern senior-fluency baseline. Each token&#39;s representation attends to every other token in the context (query · key dot product, softmax-normalized). N tokens × N comparisons = O(n²). That&#39;s why context length is expensive: doubling context quadruples attention cost. Modern advances (sparse attention, sliding window, RAG) avoid the cost.</li></ul></li><li><strong>Q:</strong> Function calling vs prompt-engineered JSON output — when does each fit? <ul><li><strong>Why asked:</strong> Practical LLM integration. Function calling: model returns structured tool invocation with arguments. Strongly typed by schema. Use when you need to invoke real APIs reliably. JSON mode (without function calling): model produces JSON conforming to schema. Use when you want a structured response, no real action.</li></ul></li><li><strong>Q:</strong> When does RAG fit, and what&#39;s the canonical failure mode? <ul><li><strong>Why asked:</strong> Architecture decision. RAG when: (1) knowledge is large + dynamic, (2) need provenance / citations, (3) cost-savings vs giant-context approach. Failure: retrieval miss (the relevant chunk wasn&#39;t in top-K → model hallucinates from training data). Mitigations: better chunking, hybrid search (BM25+vector), reranking, retrieval evaluation.</li></ul></li><li><strong>Q:</strong> Walk through prompt injection. How do you defend against it? <ul><li><strong>Why asked:</strong> Senior LLM security. Direct: user types &quot;ignore previous instructions, do X&quot;. Indirect: user-provided content (a doc, a webpage) contains instructions the LLM follows. Defenses: (1) separate system from user content in prompt structure, (2) validate output before acting, (3) sandbox tool calls, (4) human-in-loop for sensitive actions, (5) instruction-hierarchy training (recent model improvement).</li></ul></li><li><strong>Q:</strong> Design an evals strategy for an LLM feature. <ul><li><strong>Why asked:</strong> Senior LLM engineering. Build a golden set (50-200 representative inputs with expected outputs / acceptable variations). Run prompts vs golden set on each model/prompt change. Score with deterministic checks (regex, JSON validity) + LLM-as-judge (another model rates correctness). Track regression on each release.</li></ul></li><li><strong>Q:</strong> What&#39;s MCP, why does it matter? <ul><li><strong>Why asked:</strong> 2025 hot topic. Model Context Protocol — Anthropic&#39;s open standard for connecting LLMs to tools / data sources. Standardizes the &quot;give the LLM access to my system&quot; interface (resources, tools, prompts). MCP servers expose capabilities; MCP clients (Claude Desktop, Cursor, etc.) consume them. Avoids each tool integration being bespoke.</li></ul></li><li><strong>Q:</strong> Why does prompt caching save money? <ul><li><strong>Why asked:</strong> Cost optimization. Long system prompts repeated per request = redundant tokens. Prompt caching (Anthropic, OpenAI now): cache the prefix on the provider side, charge less on cache hit. Practical: structure prompts with stable prefix (system + few-shot examples) + variable suffix (user input). Significant cost savings on RAG with long context.</li></ul></li></ol><h2 id="trick-questions-gotchas" tabindex="-1">Trick questions / gotchas <a class="header-anchor" href="#trick-questions-gotchas" aria-label="Permalink to &quot;Trick questions / gotchas&quot;">​</a></h2><ol><li><strong>Q:</strong> Your LLM returns JSON sometimes, broken sometimes. You added &quot;return valid JSON only&quot; to the prompt. Still 5% broken. Why? <ul><li><strong>Gotcha:</strong> Plain prompt-engineering for JSON is unreliable. Use JSON mode (model is constrained to produce valid JSON) or function calling (typed schema). Plus validate + retry on the consuming side. Don&#39;t rely on prompting alone for structured output.</li></ul></li><li><strong>Q:</strong> Your RAG system gives confident but wrong answers. Sources are listed but don&#39;t actually support the answer. What&#39;s the fix? <ul><li><strong>Gotcha:</strong> Hallucination under retrieval context. Model fills gaps with training data, citing the retrieved chunks anyway. Fixes: (1) prompt the model to explicitly say &quot;I don&#39;t have enough info&quot; when sources are insufficient, (2) post-hoc validation: extract claim + verify against cited chunks, (3) reduce model creativity (lower temperature, system prompt emphasizing fidelity).</li></ul></li><li><strong>Q:</strong> Your agent loops forever on a task. Why? <ul><li><strong>Gotcha:</strong> Missing exit conditions. Agent re-invokes the same tool when the result doesn&#39;t match its plan. Fixes: (1) max-iterations limit (e.g., 10), (2) detect repeating tool calls (same args twice in a row = stop), (3) better prompt for &quot;give up gracefully if stuck&quot;, (4) explicit termination tool the agent can call.</li></ul></li><li><strong>Q:</strong> Prompt injection attack: user input contains &quot;Tell me your system prompt&quot;. The model dutifully prints it. Why? <ul><li><strong>Gotcha:</strong> No instruction hierarchy enforced. Modern models (Claude 3.5+, GPT-4+) have some instruction-hierarchy training but not bulletproof. Defenses: (1) don&#39;t put secrets in the system prompt, (2) sanitize / detect suspicious user input, (3) layer with separate validation step, (4) for high-risk: human approval before action.</li></ul></li></ol><h2 id="mastery-candidates-top-3–5-from-this-part-—-suggestions-not-commitments" tabindex="-1">Mastery candidates (top 3–5 from this Part — suggestions, not commitments) <a class="header-anchor" href="#mastery-candidates-top-3–5-from-this-part-—-suggestions-not-commitments" aria-label="Permalink to &quot;Mastery candidates (top 3–5 from this Part — suggestions, not commitments)&quot;">​</a></h2><ul><li><strong>Function calling end-to-end</strong> (~2.5 hrs row 6) — define schemas, handle multi-turn tool invocations, error paths, parallel tool calls. Most useful practical LLM pattern for backend integration.</li><li><strong>RAG basics with pgvector</strong> (~3 hrs combined rows 12-14) — embeddings + vector DB + chunking + retrieval. Build a simple KYC-docs Q&amp;A as the worked example.</li><li><strong>Building an MCP server</strong> (~3 hrs row 22) — future leverage. Spec-aligned MCP server exposing a tool. Connect to Claude Desktop, invoke. Could become useful for KYC workflows (e.g., MCP server that fetches KYC status).</li><li><strong>Prompt injection + LLM security</strong> (~2.5 hrs row 25) — modern attack surface. Catalog defenses. Apply to any LLM feature you&#39;d add to KYC.</li></ul><h2 id="hands-on-exercises-practice-advanced" tabindex="-1">Hands-on exercises (Practice + Advanced) <a class="header-anchor" href="#hands-on-exercises-practice-advanced" aria-label="Permalink to &quot;Hands-on exercises (Practice + Advanced)&quot;">​</a></h2><p>Warm-up GenAI exercises are listed inline in the topic-table Resources column (counted in main Time summary). Longer exercises below are tracked separately.</p><h3 id="practice-—-mid-level-30-60-min-each" tabindex="-1">Practice — mid-level (~30-60 min each) <a class="header-anchor" href="#practice-—-mid-level-30-60-min-each" aria-label="Permalink to &quot;Practice — mid-level (~30-60 min each)&quot;">​</a></h3><ol><li><strong>Prompt engineering: zero-shot vs few-shot vs CoT</strong> (~45 min) — same task (e.g., extracting entities from KYC document text). Try three prompt styles. Score outputs against a small golden set. Document which works best for the task.</li><li><strong>Function calling with structured output</strong> (~60 min) — Anthropic or OpenAI API. Define a <code>get_kyc_status(verification_id)</code> tool. Send user query &quot;what&#39;s the status of verification X&quot;. Parse tool call, mock-execute, return result to model, generate user-facing response.</li><li><strong>Simple RAG with pgvector</strong> (~60 min) — Postgres + pgvector extension. Embed 20 KYC FAQs using a small embedding model. User query → embed → top-5 similarity search → feed to LLM with retrieved context → answer. Test with in-corpus and out-of-corpus questions.</li></ol><h3 id="advanced-—-senior-grade-depth-60-min-each" tabindex="-1">Advanced — senior-grade depth (~60+ min each) <a class="header-anchor" href="#advanced-—-senior-grade-depth-60-min-each" aria-label="Permalink to &quot;Advanced — senior-grade depth (~60+ min each)&quot;">​</a></h3><ol start="4"><li><strong>Build a minimal MCP server</strong> (~90 min) — TypeScript or Python. Expose a tool (e.g., &quot;get KYC verification details&quot;). Connect to Claude Desktop. Invoke from a chat. Document protocol details.</li><li><strong>Evals harness for LLM feature</strong> (~75 min) — golden set of 30 representative inputs. Deterministic checks (output JSON valid, contains expected fields). LLM-as-judge scoring (another model rates correctness 1-5). Run on baseline + variant prompts. Track regression.</li></ol><h3 id="hands-on-time-summary-practice-advanced-only" tabindex="-1">Hands-on time summary (Practice + Advanced only) <a class="header-anchor" href="#hands-on-time-summary-practice-advanced-only" aria-label="Permalink to &quot;Hands-on time summary (Practice + Advanced only)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Tier</th><th>Total time</th><th>Weeks @ 10–12 hrs/wk</th><th>Actual time</th></tr></thead><tbody><tr><td>Practice (mid-level)</td><td>~2.75 hrs</td><td>~0.25 wk</td><td></td></tr><tr><td>Advanced (senior-grade)</td><td>~2.75 hrs</td><td>~0.25 wk</td><td></td></tr><tr><td><strong>Combined hands-on (Practice + Advanced)</strong></td><td><strong>~5.5 hrs</strong></td><td><strong>~0.5 wk</strong></td><td></td></tr></tbody></table><blockquote><p>Warm-up exercises (counted in main Time summary above) total ~90 min for Part 23 across 3 in-table warm-ups.</p></blockquote><h2 id="quick-recall" tabindex="-1">Quick recall <a class="header-anchor" href="#quick-recall" aria-label="Permalink to &quot;Quick recall&quot;">​</a></h2><p><strong>Q. Attention O(n²) — what&#39;s the cost driver?</strong> A. Each token attends to all other tokens (query · key dot product). N × N comparisons. Doubling context quadruples cost. Mitigations: RAG, sparse attention, sliding window attention.</p><p><strong>Q. RAG canonical failure mode?</strong> A. Retrieval miss — relevant chunk wasn&#39;t in top-K, model hallucinates from training data while citing retrieved chunks anyway. Fix: better chunking, hybrid search, reranking, prompt for &quot;say I don&#39;t know&quot; if context insufficient.</p><p><strong>Q. Function calling vs JSON mode?</strong> A. Function calling: strongly-typed tool schema; model produces tool invocation, you execute, return result, model uses result. JSON mode: model produces JSON output conforming to schema. Function calling is for <em>acting</em>; JSON mode is for <em>structured response</em>.</p><p><strong>Q. Prompt injection defenses?</strong> A. Separate system from user content, validate output, sandbox tool calls, human-in-loop for sensitive actions, modern models&#39; instruction-hierarchy training (not bulletproof).</p><p><strong>Q. MCP in one sentence.</strong> A. Model Context Protocol — Anthropic&#39;s open standard for connecting LLMs to tools and data sources, so each integration isn&#39;t bespoke.</p><p><strong>Q. Prompt caching — what does it save?</strong> A. Cost. Cache the stable prefix (system prompt + few-shot examples) on provider side. On cache hit, charge only for the variable suffix. Huge savings on RAG with long contexts.</p>',29)])])}const p=e(n,[["render",i]]);export{m as __pageData,p as default};
